bool isPowerOfTwo(int n) {
    // Reject non‑positive inputs; they cannot be powers of two.
    if (n <= 0) {
        return false;
    }

    // Edge case: only 1 equals 2^0, so a single‑element recursion is sufficient.
    if (n == 1) {
        return true;
    }

    // Continue recursion while the remainder is zero.
    while (n % 2 == 0) {
        n /= 2;
    }

    // A power of two must now be a single odd component.
    return (n == 1);
}

