int usingBinarySearch(int start, int end, int N, int S) {
    while (start < end) {
        const int mid = start + (end - start) / 2;               // prevent overflow
        const int totalSum = N * (N + 1) / 2;                      // sum of 1 .. N
        const int midSum = mid * (mid + 1) / 2;                   // sum of 1 .. mid
        if (totalSum - midSum <= S) {
            // feasible range: keep mid for next recursion
            end = mid;
        } else {
            // infeasible range: discard mid and mid+1 and above
            start = mid + 1;
        }
    }
    return start; // start == end; return the minimal k for which the sum of first k natural numbers is not greater than S
}

