unsigned int factorial(unsigned int n) {
    if (n == 0) return 1;                     // base case
    unsigned int result = 1;
    std::stack<unsigned int> s;
    s.push(n);                                 // start with n
    while (!s.empty()) {
        const unsigned int current = s.top();
        s.pop();
        if (current == 0) continue;           // skip zero to avoid recursion
        result *= current;                    // accumulate product
        s.push(current - 1);                  // push the next term
    }
    return result;
}

